ALTER TYPE "UserRole" ADD VALUE IF NOT EXISTS 'ADMIN_OPERATOR';
CREATE TYPE "CashExpenseReportStatus" AS ENUM ('PENDING','APPROVED','PARTIALLY_APPROVED','REJECTED','CANCELED');
CREATE TYPE "CashFundEntryType" AS ENUM ('MONTHLY_ALLOCATION','INITIAL_ALLOCATION','EXTRA_ALLOCATION','ADMIN_DEBIT','EXPENSE_APPROVAL','REVERSAL');
CREATE TYPE "InventoryRequestStatus" AS ENUM ('PENDING','APPROVED','PARTIALLY_APPROVED','REJECTED','CANCELED');
CREATE TYPE "InventoryMovementType" AS ENUM ('STOCK_IN','REQUEST_FULFILLMENT','MANUAL_ADJUSTMENT','REVERSAL');
CREATE TABLE "CashFundSettings" ("id" TEXT NOT NULL DEFAULT 'default', "defaultMonthlyAmount" DECIMAL(12,2) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CashFundSettings_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CashFundBudget" ("id" TEXT NOT NULL, "teacherId" TEXT NOT NULL, "monthlyAmount" DECIMAL(12,2) NOT NULL, "effectiveFrom" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CashFundBudget_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CashFundCategory" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CashFundCategory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CashExpenseReport" ("id" TEXT NOT NULL, "teacherId" TEXT NOT NULL, "categoryId" TEXT NOT NULL, "requestedAmount" DECIMAL(12,2) NOT NULL, "approvedAmount" DECIMAL(12,2), "concept" TEXT NOT NULL, "justification" TEXT NOT NULL, "expenseDate" TIMESTAMP(3) NOT NULL, "status" "CashExpenseReportStatus" NOT NULL DEFAULT 'PENDING', "rejectionReason" TEXT, "decisionReason" TEXT, "submittedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "decidedAt" TIMESTAMP(3), "decidedById" TEXT, "canceledAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CashExpenseReport_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CashExpenseAttachment" ("id" TEXT NOT NULL, "reportId" TEXT NOT NULL, "url" TEXT NOT NULL, "fileName" TEXT NOT NULL, "mimeType" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "CashExpenseAttachment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CashFundEntry" ("id" TEXT NOT NULL, "teacherId" TEXT NOT NULL, "type" "CashFundEntryType" NOT NULL, "amount" DECIMAL(12,2) NOT NULL, "description" TEXT NOT NULL, "occurredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdById" TEXT, "reportId" TEXT, "reversesId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "CashFundEntry_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InventoryProduct" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "unit" TEXT NOT NULL, "minimumStock" DECIMAL(12,3) NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "InventoryProduct_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InventoryRequest" ("id" TEXT NOT NULL, "teacherId" TEXT NOT NULL, "status" "InventoryRequestStatus" NOT NULL DEFAULT 'PENDING', "decisionReason" TEXT, "decidedById" TEXT, "submittedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "decidedAt" TIMESTAMP(3), "canceledAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "InventoryRequest_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InventoryRequestLine" ("id" TEXT NOT NULL, "requestId" TEXT NOT NULL, "productId" TEXT NOT NULL, "requestedQuantity" DECIMAL(12,3) NOT NULL, "approvedQuantity" DECIMAL(12,3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "InventoryRequestLine_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InventoryMovement" ("id" TEXT NOT NULL, "productId" TEXT NOT NULL, "type" "InventoryMovementType" NOT NULL, "quantity" DECIMAL(12,3) NOT NULL, "unitCost" DECIMAL(12,2), "reason" TEXT, "occurredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdById" TEXT, "requestLineId" TEXT, "reversesId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "InventoryMovement_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "CashFundBudget_teacherId_key" ON "CashFundBudget"("teacherId"); CREATE INDEX "CashFundBudget_effectiveFrom_idx" ON "CashFundBudget"("effectiveFrom"); CREATE UNIQUE INDEX "CashFundCategory_name_key" ON "CashFundCategory"("name"); CREATE INDEX "CashExpenseReport_teacherId_status_submittedAt_idx" ON "CashExpenseReport"("teacherId","status","submittedAt"); CREATE INDEX "CashExpenseReport_categoryId_expenseDate_idx" ON "CashExpenseReport"("categoryId","expenseDate"); CREATE INDEX "CashExpenseAttachment_reportId_idx" ON "CashExpenseAttachment"("reportId"); CREATE UNIQUE INDEX "CashFundEntry_reversesId_key" ON "CashFundEntry"("reversesId"); CREATE INDEX "CashFundEntry_teacherId_occurredAt_idx" ON "CashFundEntry"("teacherId","occurredAt"); CREATE INDEX "CashFundEntry_type_occurredAt_idx" ON "CashFundEntry"("type","occurredAt"); CREATE UNIQUE INDEX "InventoryProduct_name_unit_key" ON "InventoryProduct"("name","unit"); CREATE INDEX "InventoryRequest_teacherId_status_submittedAt_idx" ON "InventoryRequest"("teacherId","status","submittedAt"); CREATE UNIQUE INDEX "InventoryRequestLine_requestId_productId_key" ON "InventoryRequestLine"("requestId","productId"); CREATE INDEX "InventoryRequestLine_productId_idx" ON "InventoryRequestLine"("productId"); CREATE UNIQUE INDEX "InventoryMovement_reversesId_key" ON "InventoryMovement"("reversesId"); CREATE INDEX "InventoryMovement_productId_occurredAt_idx" ON "InventoryMovement"("productId","occurredAt"); CREATE INDEX "InventoryMovement_type_occurredAt_idx" ON "InventoryMovement"("type","occurredAt");
ALTER TABLE "CashFundBudget" ADD CONSTRAINT "CashFundBudget_teacherId_fkey" FOREIGN KEY ("teacherId") REFERENCES "TeacherProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "CashExpenseReport" ADD CONSTRAINT "CashExpenseReport_teacherId_fkey" FOREIGN KEY ("teacherId") REFERENCES "TeacherProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "CashExpenseReport" ADD CONSTRAINT "CashExpenseReport_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "CashFundCategory"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "CashExpenseAttachment" ADD CONSTRAINT "CashExpenseAttachment_reportId_fkey" FOREIGN KEY ("reportId") REFERENCES "CashExpenseReport"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "CashFundEntry" ADD CONSTRAINT "CashFundEntry_teacherId_fkey" FOREIGN KEY ("teacherId") REFERENCES "TeacherProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "CashFundEntry" ADD CONSTRAINT "CashFundEntry_reportId_fkey" FOREIGN KEY ("reportId") REFERENCES "CashExpenseReport"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "InventoryRequest" ADD CONSTRAINT "InventoryRequest_teacherId_fkey" FOREIGN KEY ("teacherId") REFERENCES "TeacherProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "InventoryRequestLine" ADD CONSTRAINT "InventoryRequestLine_requestId_fkey" FOREIGN KEY ("requestId") REFERENCES "InventoryRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "InventoryRequestLine" ADD CONSTRAINT "InventoryRequestLine_productId_fkey" FOREIGN KEY ("productId") REFERENCES "InventoryProduct"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "InventoryMovement" ADD CONSTRAINT "InventoryMovement_productId_fkey" FOREIGN KEY ("productId") REFERENCES "InventoryProduct"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "InventoryMovement" ADD CONSTRAINT "InventoryMovement_requestLineId_fkey" FOREIGN KEY ("requestLineId") REFERENCES "InventoryRequestLine"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
